    const ass2 = await postarJson(`/api/formularios-publico/${f.id}/assinar`, { token: tokenDoLink('gerente'), nome: 'Marcela', imagem: PNG });
    const dAss2 = ass2.status === 200 ? JSON.parse(ass2.corpo) : {};
