      'pizza nunca é excluída, mesmo com nome que está na lista':
        prev.temDivergencia({ nome: 'Perflex', tipo: 'pizza', saida: -4 }, 'saida') === true
        && prev.temDivergencia({ nome: 'Perflex', tipo: 'insumo', saida: -4 }, 'saida') === false,
