    const comNovo = await ls.definirApelidoDispositivo(OUTRA, MAC_ROTEADOR, { apelido: 'Roteador da sala', tipoNovo: 'Roteador Wi-Fi' });
    const criado = (await ls.listarTiposDispositivo()).find((t) => t.id === 'roteador-wi-fi');

